import { test } from 'node:test';
import { strict as assert } from 'node:assert';
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createAssistantMessageEventStream } from '@earendil-works/pi-ai';
import { DefaultResourceLoader, createAgentSession, SessionManager } from '@earendil-works/pi-coding-agent';

test('inherits a discovered skill hidden by an earlier runtime handler', async () => {
 const root=mkdtempSync(join(tmpdir(),'discovered-skill-')),agentDir=mkdtempSync(join(tmpdir(),'discovered-skill-cfg-'));
 execFileSync('git',['init','-q',root]);mkdirSync(join(root,'.pi','agents'),{recursive:true});const skillDir=join(root,'custom-skills','demo');mkdirSync(skillDir,{recursive:true});
 writeFileSync(join(root,'.pi','agents','worker.md'),'---\nname: worker\ndescription: worker\n---\nWork.');writeFileSync(join(skillDir,'SKILL.md'),'---\nname: demo\ndescription: discovered skill\n---\nWork.');
 const earlier=join(root,'earlier.js'),extensionPath=new URL('../extensions/index.ts',import.meta.url).pathname;
 writeFileSync(earlier,`export default pi=>{pi.on('resources_discover',()=>({skillPaths:[${JSON.stringify(skillDir)}]}));pi.on('before_agent_start',event=>{if(pi.getActiveTools().includes('subagent_start')){const skill=event.systemPromptOptions.skills.find(item=>item.name==='demo');if(skill)skill.disableModelInvocation=true;}});};`);
 const previousDir=process.env.PI_CODING_AGENT_DIR,previousArgv=process.argv;process.env.PI_CODING_AGENT_DIR=agentDir;process.argv=['node','pi','-e',earlier,'-e',extensionPath];
 const model:any={id:'fake',name:'fake',provider:'fake',api:'openai-completions',baseUrl:'http://example.invalid',reasoning:false,input:['text'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:10000,maxTokens:1000};let calls=0,childContext='';
 const eventStream=(content:any[],reason:string)=>{const stream=createAssistantMessageEventStream();const message:any={role:'assistant',content,api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:reason,timestamp:Date.now()};queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:reason as any,message});stream.end();});return stream;};
 const loader=new DefaultResourceLoader({cwd:root,agentDir,additionalExtensionPaths:[earlier,extensionPath]});await loader.reload();const {session}=await createAgentSession({cwd:root,agentDir,model,resourceLoader:loader,sessionManager:SessionManager.inMemory(root)});
 session.modelRuntime.registerProvider('fake',{api:'openai-completions',apiKey:'fake',models:[model],streamSimple:(_model,context)=>{childContext=JSON.stringify(context);return eventStream([{type:'text',text:'done'}],'stop');}});session.modelRuntime.hasConfiguredAuth=()=>true;
 session.agent.streamFunction=(()=>++calls===1?eventStream([{type:'toolCall',id:'start',name:'subagent_start',arguments:{agent:'worker',task:'work',mode:'wait',workspace:'shared'}}],'toolUse'):eventStream([{type:'text',text:'done'}],'stop')) as any;
 try {await session.bindExtensions({mode:'print'});await session.prompt('Start child');const result=session.messages.find(message=>message.role==='toolResult');assert.ok(result && result.role==='toolResult' && !result.isError,JSON.stringify(result));assert.equal(JSON.parse((result.content[0] as any).text).done[0].state,'completed');assert.doesNotMatch(childContext,/<name>demo<\/name>/);}
 finally {await session.extensionRunner.emit({type:'session_shutdown',reason:'quit'});session.dispose();process.argv=previousArgv;if(previousDir===undefined)delete process.env.PI_CODING_AGENT_DIR;else process.env.PI_CODING_AGENT_DIR=previousDir;}
});

test('worktree child discovers the same settings-selected skill as its Pi parent', async () => {
 const root=mkdtempSync(join(tmpdir(),'skill-integration-')),agentDir=mkdtempSync(join(tmpdir(),'skill-integration-cfg-'));
 const git=(...args:string[])=>execFileSync('git',args,{cwd:root,stdio:'ignore'});git('init');git('config','commit.gpgsign','false');git('config','user.email','test@example.test');git('config','user.name','Test');
 mkdirSync(join(root,'.pi','agents'),{recursive:true});mkdirSync(join(root,'.pi','extensions'),{recursive:true});mkdirSync(join(root,'custom-skill'));
 writeFileSync(join(root,'.pi','extensions','policy.js'),`export default pi=>pi.on('before_agent_start',event=>{if(pi.getActiveTools().includes('subagent_start'))event.systemPromptOptions.sections.project_policy='WORKTREE_POLICY_SENTINEL';});`);
 writeFileSync(join(root,'.pi','agents','worker.md'),'---\nname: worker\ndescription: worker\n---\nWork.');writeFileSync(join(root,'.pi','settings.json'),JSON.stringify({skills:['../custom-skill']}));writeFileSync(join(root,'custom-skill','SKILL.md'),'---\nname: custom-test-skill\ndescription: custom skill sentinel\n---\nbody');git('add','.');git('commit','-m','base');
 const previous=process.env.PI_CODING_AGENT_DIR;process.env.PI_CODING_AGENT_DIR=agentDir;
 const model:any={id:'fake',name:'fake',provider:'fake',api:'openai-completions',baseUrl:'http://example.invalid',reasoning:false,input:['text'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:10000,maxTokens:1000};let childContext='';
 const eventStream=(content:any[],reason:string)=>{const stream=createAssistantMessageEventStream();const message:any={role:'assistant',content,api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:reason,timestamp:Date.now()};queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:reason as any,message});stream.end();});return stream;};
 const loader=new DefaultResourceLoader({cwd:root,agentDir,additionalExtensionPaths:[new URL('../extensions/index.ts',import.meta.url).pathname]});await loader.reload();
 const {session}=await createAgentSession({cwd:root,agentDir,model,resourceLoader:loader,sessionManager:SessionManager.inMemory(root)});
 session.modelRuntime.registerProvider('fake',{api:'openai-completions',apiKey:'fake',models:[model],streamSimple:(_m,context)=>{childContext=JSON.stringify(context);return eventStream([{type:'text',text:'done'}],'stop');}});session.modelRuntime.hasConfiguredAuth=()=>true;let calls=0;
 session.agent.streamFunction=(()=>++calls===1 ? eventStream([{type:'toolCall',id:'start',name:'subagent_start',arguments:{agent:'worker',task:'work',mode:'wait',workspace:'worktree'}}],'toolUse') : eventStream([{type:'text',text:'done'}],'stop')) as any;
 try {
  await session.bindExtensions({mode:'print'});await session.prompt('Start a child');
  const result=session.messages.find(message=>message.role==='toolResult');assert.ok(result && result.role==='toolResult' && !result.isError,JSON.stringify(result));
  const payload=JSON.parse((result.content[0] as any).text);assert.equal(payload.done[0].state,'completed',JSON.stringify(payload));assert.match(childContext,/custom skill sentinel/);assert.match(childContext,/subagent-worktrees.*custom-skill/);assert.match(childContext,/WORKTREE_POLICY_SENTINEL/);
 } finally {await session.extensionRunner.emit({type:'session_shutdown',reason:'quit'});session.dispose();if(previous===undefined)delete process.env.PI_CODING_AGENT_DIR;else process.env.PI_CODING_AGENT_DIR=previous;}
});

test('rejects a worktree skill whose model visibility changed after parent load', async () => {
 const root=mkdtempSync(join(tmpdir(),'skill-integration-')),agentDir=mkdtempSync(join(tmpdir(),'skill-integration-cfg-'));
 const git=(...args:string[])=>execFileSync('git',args,{cwd:root,stdio:'ignore'});git('init');git('config','commit.gpgsign','false');git('config','user.email','test@example.test');git('config','user.name','Test');
 mkdirSync(join(root,'.pi','agents'),{recursive:true});mkdirSync(join(root,'custom-skill'));
 writeFileSync(join(root,'.pi','agents','worker.md'),'---\nname: worker\ndescription: worker\n---\nWork.');writeFileSync(join(root,'.pi','settings.json'),JSON.stringify({skills:['../custom-skill']}));writeFileSync(join(root,'custom-skill','SKILL.md'),'---\nname: custom-test-skill\ndescription: custom skill sentinel\n---\nbody');git('add','.');git('commit','-m','base');
 writeFileSync(join(root,'custom-skill','SKILL.md'),'---\nname: custom-test-skill\ndescription: custom skill sentinel\ndisable-model-invocation: true\n---\nbody');
 const previous=process.env.PI_CODING_AGENT_DIR;process.env.PI_CODING_AGENT_DIR=agentDir;
 const model:any={id:'fake',name:'fake',provider:'fake',api:'openai-completions',baseUrl:'http://example.invalid',reasoning:false,input:['text'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:10000,maxTokens:1000};let childContext='';
 const eventStream=(content:any[],reason:string)=>{const stream=createAssistantMessageEventStream();const message:any={role:'assistant',content,api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:reason,timestamp:Date.now()};queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:reason as any,message});stream.end();});return stream;};
 const loader=new DefaultResourceLoader({cwd:root,agentDir,additionalExtensionPaths:[new URL('../extensions/index.ts',import.meta.url).pathname]});await loader.reload();writeFileSync(join(root,'custom-skill','SKILL.md'),'---\nname: custom-test-skill\ndescription: custom skill sentinel\n---\nbody');
 const {session}=await createAgentSession({cwd:root,agentDir,model,resourceLoader:loader,sessionManager:SessionManager.inMemory(root)});
 session.modelRuntime.registerProvider('fake',{api:'openai-completions',apiKey:'fake',models:[model],streamSimple:(_m,context)=>{childContext=JSON.stringify(context);return eventStream([{type:'text',text:'done'}],'stop');}});session.modelRuntime.hasConfiguredAuth=()=>true;let calls=0;
 session.agent.streamFunction=(()=>++calls===1 ? eventStream([{type:'toolCall',id:'start',name:'subagent_start',arguments:{agent:'worker',task:'work',mode:'wait',workspace:'worktree'}}],'toolUse') : eventStream([{type:'text',text:'done'}],'stop')) as any;
 try {
  await session.bindExtensions({mode:'print'});await session.prompt('Start a child');
  const result=session.messages.find(message=>message.role==='toolResult');assert.ok(result && result.role==='toolResult' && !result.isError,JSON.stringify(result));
  const payload=JSON.parse((result.content[0] as any).text);assert.equal(payload.done[0].state,'failed',JSON.stringify(payload));assert.match(payload.done[0].error,/visibility differs/);assert.equal(childContext,'');
 } finally {await session.extensionRunner.emit({type:'session_shutdown',reason:'quit'});session.dispose();if(previous===undefined)delete process.env.PI_CODING_AGENT_DIR;else process.env.PI_CODING_AGENT_DIR=previous;}
});

test('README skill command expands for a parent that starts the named agent', async () => {
 const {readFileSync}=await import('node:fs');
 const root=mkdtempSync(join(tmpdir(),'skill-command-')),agentDir=mkdtempSync(join(tmpdir(),'skill-command-cfg-'));
 execFileSync('git',['init',root],{stdio:'ignore'});mkdirSync(join(root,'.pi','agents'),{recursive:true});mkdirSync(join(root,'.pi','skills','review-changes'),{recursive:true});
 writeFileSync(join(root,'.pi','agents','reviewer.md'),'---\nname: reviewer\ndescription: review\n---\nReview carefully.');
 const readme=readFileSync(new URL('../README.md',import.meta.url),'utf8');const example=readme.split('`.pi/skills/review-changes/SKILL.md`')[1]?.match(/```markdown\n([\s\S]*?)\n```/)?.[1];assert.ok(example);writeFileSync(join(root,'.pi','skills','review-changes','SKILL.md'),example);
 const previous=process.env.PI_CODING_AGENT_DIR;process.env.PI_CODING_AGENT_DIR=agentDir;
 const model:any={id:'fake',name:'fake',provider:'fake',api:'openai-completions',baseUrl:'http://example.invalid',reasoning:false,input:['text'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:10000,maxTokens:1000};
 const eventStream=(content:any[],reason:string)=>{const stream=createAssistantMessageEventStream();const message:any={role:'assistant',content,api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:reason,timestamp:Date.now()};queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:reason as any,message});stream.end();});return stream;};
 const loader=new DefaultResourceLoader({cwd:root,agentDir,additionalExtensionPaths:[new URL('../extensions/index.ts',import.meta.url).pathname]});await loader.reload();
 const {session}=await createAgentSession({cwd:root,agentDir,model,resourceLoader:loader,sessionManager:SessionManager.inMemory(root)});let parentContext='',calls=0;
 session.modelRuntime.registerProvider('fake',{api:'openai-completions',apiKey:'fake',models:[model],streamSimple:()=>eventStream([{type:'text',text:'Review finished'}],'stop')});session.modelRuntime.hasConfiguredAuth=()=>true;
 session.agent.streamFunction=((_model:any,context:any)=>{if(++calls===1){parentContext=JSON.stringify(context);return eventStream([{type:'toolCall',id:'start',name:'subagent_start',arguments:{agent:'reviewer',task:'Review current changes',mode:'wait',workspace:'shared'}}],'toolUse');}return eventStream([{type:'text',text:'Reported'}],'stop');}) as any;
 try {await session.bindExtensions({mode:'print'});await session.prompt('/skill:review-changes Review current changes');assert.match(parentContext,/subagent_start/);assert.match(parentContext,/Review current changes/);const result=session.messages.find(message=>message.role==='toolResult');assert.ok(result && result.role==='toolResult' && !result.isError);assert.equal(JSON.parse((result.content[0] as any).text).done[0].result,'Review finished');}
 finally {await session.extensionRunner.emit({type:'session_shutdown',reason:'quit'});session.dispose();if(previous===undefined)delete process.env.PI_CODING_AGENT_DIR;else process.env.PI_CODING_AGENT_DIR=previous;}
});

test('real Pi parent rejects child launch after MCP extension settings drift', async () => {
 const {createMcpExtension,createCodemodeExtension}=await import('@earendil-works/pi-coding-agent');
 const root=mkdtempSync(join(tmpdir(),'mcp-drift-sdk-')),agentDir=mkdtempSync(join(tmpdir(),'mcp-drift-sdk-cfg-'));
 execFileSync('git',['init',root],{stdio:'ignore'});mkdirSync(join(root,'.pi','agents'),{recursive:true});writeFileSync(join(root,'.pi','agents','worker.md'),'---\nname: worker\ndescription: worker\n---\nWork.');
 const previous=process.env.PI_CODING_AGENT_DIR;process.env.PI_CODING_AGENT_DIR=agentDir;
 const model:any={id:'fake',name:'fake',provider:'fake',api:'openai-completions',baseUrl:'http://example.invalid',reasoning:false,input:['text'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:10000,maxTokens:1000};
 const loader=new DefaultResourceLoader({cwd:root,agentDir,additionalExtensionPaths:[new URL('../extensions/index.ts',import.meta.url).pathname],extensionFactories:[createCodemodeExtension({mode:'on'}),createMcpExtension()]});await loader.reload();
 const {session}=await createAgentSession({cwd:root,agentDir,model,resourceLoader:loader,sessionManager:SessionManager.inMemory(root)});session.modelRuntime.registerProvider('fake',{api:'openai-completions',apiKey:'fake',models:[model],streamSimple:()=>{const stream=createAssistantMessageEventStream();const message:any={role:'assistant',content:[{type:'text',text:'child completed'}],api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:'stop',timestamp:Date.now()};queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:'stop',message});stream.end();});return stream;}});session.modelRuntime.hasConfiguredAuth=()=>true;let calls=0;
 session.agent.streamFunction=(()=>{const first=calls++===0,stream=createAssistantMessageEventStream();const message:any={role:'assistant',content:first?[{type:'toolCall',id:'start',name:'subagent_start',arguments:{agent:'worker',task:'work',mode:'wait',workspace:'shared'}}]:[{type:'text',text:'done'}],api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:first?'toolUse':'stop',timestamp:Date.now()};queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:message.stopReason,message});stream.end();});return stream;}) as any;
 try {await session.bindExtensions({mode:'print'});session.setActiveToolsByName([...session.getActiveToolNames(),'codemode']);await session.prompt('Start child');const first=session.messages.find(message=>message.role==='toolResult');assert.ok(first && first.role==='toolResult' && !first.isError,JSON.stringify(first));assert.equal(JSON.parse((first.content[0] as any).text).done[0].result,'child completed');calls=0;writeFileSync(join(agentDir,'settings.json'),JSON.stringify({extensions:['-builtin:mcp']}));await session.prompt('Start another child');const result=[...session.messages].reverse().find(message=>message.role==='toolResult');assert.ok(result && result.role==='toolResult' && result.isError,JSON.stringify(result));assert.match(JSON.stringify(result.content),/MCP configuration changed/);}
 finally {await session.extensionRunner.emit({type:'session_shutdown',reason:'quit'});session.dispose();if(previous===undefined)delete process.env.PI_CODING_AGENT_DIR;else process.env.PI_CODING_AGENT_DIR=previous;}
});

