test('worktree resolves a runtime relative context from the parent subdirectory', async () => {
 const root=mkdtempSync(join(tmpdir(),'relative-context-sdk-')),agentDir=mkdtempSync(join(tmpdir(),'relative-context-sdk-cfg-')),cwd=join(root,'nested');execFileSync('git',['init',root],{stdio:'ignore'});mkdirSync(join(root,'.pi','agents'),{recursive:true});mkdirSync(join(cwd,'.pi','extensions'),{recursive:true});writeFileSync(join(root,'.pi','agents','worker.md'),'---\nname: worker\ndescription: worker\n---\nWork.');writeFileSync(join(cwd,'policy.md'),'RELATIVE_POLICY_SENTINEL');writeFileSync(join(cwd,'.pi','extensions','policy.js'),`export default pi=>pi.on('before_agent_start',event=>{if(pi.getActiveTools().includes('subagent_start'))event.systemPromptOptions.contextFiles.push({path:'policy.md',content:'RELATIVE_POLICY_SENTINEL'});});`);execFileSync('git',['add','.'],{cwd:root,stdio:'ignore'});execFileSync('git',['-c','commit.gpgsign=false','-c','user.name=Test','-c','user.email=test@example.invalid','commit','-qm','fixture'],{cwd:root,stdio:'ignore'});
 const previous=process.env.PI_CODING_AGENT_DIR;process.env.PI_CODING_AGENT_DIR=agentDir;const model:any={id:'fake',name:'fake',provider:'fake',api:'openai-completions',baseUrl:'http://example.invalid',reasoning:false,input:['text'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:10000,maxTokens:1000};let childContext='',calls=0;
 const eventStream=(content:any[],reason:string)=>{const stream=createAssistantMessageEventStream();const message:any={role:'assistant',content,api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:reason,timestamp:Date.now()};queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:reason as any,message});stream.end();});return stream;};
 const loader=new DefaultResourceLoader({cwd,agentDir,additionalExtensionPaths:[new URL('../extensions/index.ts',import.meta.url).pathname]});await loader.reload();const {session}=await createAgentSession({cwd,agentDir,model,resourceLoader:loader,sessionManager:SessionManager.inMemory(cwd)});session.modelRuntime.registerProvider('fake',{api:'openai-completions',apiKey:'fake',models:[model],streamSimple:(_model,context)=>{childContext=JSON.stringify(context);return eventStream([{type:'text',text:'done'}],'stop');}});session.modelRuntime.hasConfiguredAuth=()=>true;
 session.agent.streamFunction=(()=>++calls===1?eventStream([{type:'toolCall',id:'start',name:'subagent_start',arguments:{agent:'worker',task:'work',mode:'wait',workspace:'worktree'}}],'toolUse'):eventStream([{type:'text',text:'done'}],'stop')) as any;
 try {await session.bindExtensions({mode:'print'});await session.prompt('Start child');const result=session.messages.find(message=>message.role==='toolResult');assert.ok(result && result.role==='toolResult' && !result.isError,JSON.stringify(result));assert.equal(JSON.parse((result.content[0] as any).text).done[0].state,'completed');assert.match(childContext,/subagent-worktrees.*nested.*policy\.md/);assert.match(childContext,/RELATIVE_POLICY_SENTINEL/);}
 finally {await session.extensionRunner.emit({type:'session_shutdown',reason:'quit'});session.dispose();if(previous===undefined)delete process.env.PI_CODING_AGENT_DIR;else process.env.PI_CODING_AGENT_DIR=previous;}
});

for (const order of ['normal','early'] as const) for (const workspace of ['shared','worktree'] as const) for (const action of ['add','remove','description','hide','show'] as const) test(`${order} ${workspace} inherits parent runtime skill ${action}`, async () => {
 const root=mkdtempSync(join(tmpdir(),'runtime-skill-parent-')),agentDir=mkdtempSync(join(tmpdir(),'runtime-skill-cfg-'));const git=(...args:string[])=>execFileSync('git',args,{cwd:root,stdio:'ignore'});git('init');git('config','commit.gpgsign','false');git('config','user.email','test@example.invalid');git('config','user.name','Test');
 mkdirSync(join(root,'.pi','agents'),{recursive:true});mkdirSync(join(root,'.pi','extensions'),{recursive:true});mkdirSync(join(root,'.pi','skills','original'),{recursive:true});mkdirSync(join(root,'.pi','dynamic','extra'),{recursive:true});writeFileSync(join(root,'.pi','agents','worker.md'),'---\nname: worker\ndescription: worker\n---\nWork.');writeFileSync(join(root,'.pi','skills','original','SKILL.md'),`---\nname: original-test-skill\ndescription: Original skill sentinel\n${action==='show'?'disable-model-invocation: true\n':''}---\nbody`);writeFileSync(join(root,'.pi','dynamic','extra','SKILL.md'),'---\nname: added-test-skill\ndescription: Added skill sentinel\n---\nbody');
 const extra=join(root,'.pi','dynamic','extra','SKILL.md');writeFileSync(join(root,'.pi','extensions','skill.js'),`export default pi=>pi.on('before_agent_start',event=>{if(!pi.getActiveTools().includes('subagent_start'))return;const original=event.systemPromptOptions.skills.find(s=>s.name==='original-test-skill');if(!original)throw new Error('missing fixture skill');${action==='add'?`event.systemPromptOptions.skills.push({...original,name:'added-test-skill',description:'Added runtime sentinel',filePath:${JSON.stringify(extra)},baseDir:${JSON.stringify(join(root,'.pi','dynamic','extra'))}});`:action==='remove'?`event.systemPromptOptions.skills=event.systemPromptOptions.skills.filter(s=>s.name!=='original-test-skill');`:action==='description'?`original.description='Modified runtime sentinel';`:action==='hide'?`original.disableModelInvocation=true;`:`original.disableModelInvocation=false;`}});`);git('add','.');git('commit','-m','fixture');
 const previous=process.env.PI_CODING_AGENT_DIR;process.env.PI_CODING_AGENT_DIR=agentDir;const model:any={id:'fake',name:'fake',provider:'fake',api:'openai-completions',baseUrl:'http://example.invalid',reasoning:false,input:['text'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:10000,maxTokens:1000};let childContext='',calls=0;
 const eventStream=(content:any[],reason:string)=>{const stream=createAssistantMessageEventStream();const message:any={role:'assistant',content,api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:reason,timestamp:Date.now()};queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:reason as any,message});stream.end();});return stream;};
 const loader=new DefaultResourceLoader({cwd:root,agentDir,additionalExtensionPaths:order==='early'?[join(root,'.pi','extensions','skill.js'),new URL('../extensions/index.ts',import.meta.url).pathname]:[new URL('../extensions/index.ts',import.meta.url).pathname]});await loader.reload();const {session}=await createAgentSession({cwd:root,agentDir,model,resourceLoader:loader,sessionManager:SessionManager.inMemory(root)});session.modelRuntime.registerProvider('fake',{api:'openai-completions',apiKey:'fake',models:[model],streamSimple:(_model,context)=>{childContext=JSON.stringify(context);return eventStream([{type:'text',text:'done'}],'stop');}});session.modelRuntime.hasConfiguredAuth=()=>true;
 session.agent.streamFunction=(()=>++calls===1?eventStream([{type:'toolCall',id:'start',name:'subagent_start',arguments:{agent:'worker',task:'work',mode:'wait',workspace}}],'toolUse'):eventStream([{type:'text',text:'done'}],'stop')) as any;
 try {await session.bindExtensions({mode:'print'});await session.prompt('Start child');const result=session.messages.find(message=>message.role==='toolResult');assert.ok(result && result.role==='toolResult' && !result.isError,JSON.stringify(result));assert.equal(JSON.parse((result.content[0] as any).text).done[0].state,'completed');if(action==='add')assert.match(childContext,/Added runtime sentinel/);if(action==='remove')assert.doesNotMatch(childContext,/original-test-skill/);if(action==='description')assert.match(childContext,/Modified runtime sentinel/);if(action==='hide')assert.doesNotMatch(childContext,/original-test-skill/);if(action==='show')assert.match(childContext,/original-test-skill/);if(action==='add'&&workspace==='worktree')assert.match(childContext,/subagent-worktrees.*dynamic.*extra.*SKILL/);}
 finally {await session.extensionRunner.emit({type:'session_shutdown',reason:'quit'});session.dispose();if(previous===undefined)delete process.env.PI_CODING_AGENT_DIR;else process.env.PI_CODING_AGENT_DIR=previous;}
});
